// Engine mascots: every engine gets an original pixel character whose body
// comes from the engine's name (a moon for Kimi, a question mark for Qwen, a
// codex book for Codex …), never from a company logo. The official logo stays
// where it belongs — in the small icon slot on a name tag (ProviderMark).
//
// The art lives in src/assets/mascots/ and is generated by
// scripts/mascots/generate.py; the row/column order below must match it.
import { msg } from "@/lib/i18n";

export const MASCOT_KINDS = [
  "workbuddy",
  "claude",
  "codex",
  "kimi",
  "qwen",
  "grok",
  "hermes",
  "droid",
  "cursor",
  "antigravity",
  "opencode",
  "pi",
  "local",
  "pc",
] as const;
export type MascotKind = (typeof MASCOT_KINDS)[number];

/** Columns of mascots.png. A pose is how a figure tells its state at a glance. */
export const MASCOT_POSES = ["idle", "work", "wave", "cheer", "think", "point", "run", "scared"] as const;
export type MascotPose = (typeof MASCOT_POSES)[number];

/** Each engine's brand colour; tiles are tinted with it, never painted in it. */
export const MASCOT_BRAND: Record<MascotKind, string> = {
  workbuddy: "#3B82F6",
  claude: "#D97757",
  codex: "#22C55E",
  kimi: "#1783FF",
  qwen: "#6336E7",
  grok: "#6B7280",
  hermes: "#14B8A6",
  droid: "#F97316",
  cursor: "#6B7280",
  antigravity: "#7DD3FC",
  opencode: "#4ADE80",
  pi: "#6B7280",
  local: "#16A34A",
  pc: "#38BDF8",
};

/** What the body is, for tooltips and the about-the-mascots page. */
export const MASCOT_BODY: Record<MascotKind, string> = {
  workbuddy: msg("Toolbox"),
  claude: msg("Brick golem"),
  codex: msg("Codex book"),
  kimi: msg("Crescent moon"),
  qwen: msg("Question mark"),
  grok: msg("Martian"),
  hermes: msg("Winged letter"),
  droid: msg("Gear"),
  cursor: msg("Pointer"),
  antigravity: msg("Floating cube"),
  opencode: msg("Code window"),
  pi: msg("π"),
  local: msg("Chip"),
  pc: msg("Monitor"),
};

const DRIVER_MASCOT: Record<string, MascotKind> = {
  workbuddyAgent: "workbuddy",
  claudeAgent: "claude",
  codex: "codex",
  kimiAgent: "kimi",
  qwenAgent: "qwen",
  grok: "grok",
  grokAgent: "grok",
  hermesAgent: "hermes",
  droidAgent: "droid",
  cursorAgent: "cursor",
  antigravityAgent: "antigravity",
  opencodeGo: "opencode",
  piAgent: "pi",
  boxAgent: "pc",
};

/** The mascot for an engine driver. Local-model runtimes (Ollama, LM Studio,
 * any OpenAI-compatible server on this machine) share the chip; anything else
 * unknown falls back to the WorkBuddy toolbox, the default engine. */
export function mascotForDriver(driverKind: string | null | undefined): MascotKind {
  if (!driverKind) return "workbuddy";
  const known = DRIVER_MASCOT[driverKind];
  if (known) return known;
  if (/ollama|lmstudio|lm-studio|local|llama|openai-?compat/i.test(driverKind)) return "local";
  // Instance ids usually carry the engine's name ("kimi", "claude-work",
  // "box"), which is all there is to go on before the engine list loads.
  const name = driverKind.toLowerCase().replace(/agent$|go$/, "");
  if (name.startsWith("box")) return "pc";
  const kind = MASCOT_KINDS.find((k) => k !== "local" && k !== "pc" && name.startsWith(k));
  return kind ?? "workbuddy";
}

/** Status words used across the app, mapped to the pose that shows them. */
export type MascotStatus = "idle" | "queued" | "working" | "waiting" | "done" | "failed" | "stuck" | "disagree" | "leading" | "rushing";

export function poseForStatus(status: MascotStatus): MascotPose {
  switch (status) {
    case "working":
      return "work";
    case "waiting":
      return "wave";
    case "done":
      return "cheer";
    case "failed":
    case "stuck":
      return "scared";
    case "disagree":
      return "think";
    case "leading":
      return "point";
    case "rushing":
      return "run";
    default:
      return "idle";
  }
}

/** Brand colour mixed toward white — the soft tile ground behind a bust. */
export function tint(hex: string, toWhite: number): string {
  const h = hex.replace("#", "");
  const ch = (i: number) => parseInt(h.slice(i, i + 2), 16);
  const mix = (v: number) => Math.round(v + (255 - v) * toWhite);
  return `#${[ch(0), ch(2), ch(4)].map((v) => mix(v).toString(16).padStart(2, "0")).join("")}`;
}

/** Minimal shapes so this module stays free of the store's types. */
type InstanceLike = { instanceId: string; driverKind: string; models?: { options: Array<{ id: string; custom?: boolean }> } };
type BotLike = { modelSelection?: { instanceId: string; model?: string } | null };

/** The mascot for a bot: its engine's, resolved through the instance it runs
 * on. A bot on a local model gets the chip even when the driver is a cloud
 * engine's. */
export function mascotForBot(bot: BotLike, instances: readonly InstanceLike[]): MascotKind {
  const selection = bot.modelSelection;
  if (!selection) return "workbuddy";
  const instance = instances.find((i) => i.instanceId === selection.instanceId);
  if (!instance) return mascotForDriver(selection.instanceId);
  // A model the app marks as local (Ollama, LM Studio …), or an engine that is
  // nothing but an OpenAI-compatible server, is "running on your machine".
  const option = instance.models?.options.find((o) => o.id === selection.model);
  if (option?.custom || instance.driverKind === "openai-compat") return "local";
  return mascotForDriver(instance.driverKind);
}
